// Regenerates public/resume.pdf from the built /resume page, and records a
// hash of that page's text so verify-build.mjs can tell when the PDF has gone
// stale.
//
//   npm run build
//   node scripts/make-resume-pdf.mjs
//
// Needs Playwright's Chromium, which is NOT a project dependency — the PDF is
// regenerated by hand on the rare occasions the résumé changes, and CI only
// verifies freshness rather than rebuilding it. If Playwright is missing:
//
//   npx --yes playwright@latest install --with-deps chromium
//
// Nothing here runs during `npm run build`; a missing browser can never break
// a deploy.

import { createServer } from 'node:http';
import { readFileSync, writeFileSync, existsSync, statSync } from 'node:fs';
import { join, extname } from 'node:path';
import { createHash } from 'node:crypto';
import { resumeText } from './resume-text.mjs';

const OUT = 'out';
const PORT = 8123;

if (!existsSync(join(OUT, 'resume', 'index.html'))) {
  console.error('No build found. Run `npm run build` first.');
  process.exit(1);
}

const TYPES = {
  '.html': 'text/html', '.css': 'text/css', '.js': 'text/javascript',
  '.webp': 'image/webp', '.woff2': 'font/woff2', '.ico': 'image/x-icon',
  '.svg': 'image/svg+xml', '.json': 'application/json',
};

// Serve out/ the way GitHub Pages does, so the PDF is made from exactly the
// bytes that ship.
const server = createServer((req, res) => {
  const p = decodeURIComponent(new URL(req.url, 'http://x').pathname);
  let file = join(OUT, p);
  // A route like /resume resolves to a DIRECTORY holding index.html
  // (trailingSlash: true). Testing existence alone is not enough — the
  // directory exists, and reading it as a file throws EISDIR.
  if (existsSync(file) && statSync(file).isDirectory()) file = join(file, 'index.html');
  if (!existsSync(file)) file = join(OUT, `${p}.html`);
  if (!existsSync(file)) { res.writeHead(404).end('not found'); return; }
  res.writeHead(200, { 'content-type': TYPES[extname(file)] ?? 'application/octet-stream' });
  res.end(readFileSync(file));
});

await new Promise((r) => server.listen(PORT, r));

let chromium;
try {
  ({ chromium } = await import('playwright'));
} catch {
  console.error('Playwright not installed. See the comment at the top of this file.');
  server.close();
  process.exit(1);
}

const browser = await chromium.launch();
const page = await browser.newPage();
await page.goto(`http://127.0.0.1:${PORT}/resume`, { waitUntil: 'networkidle' });
await page.emulateMedia({ media: 'print' });
await page.pdf({
  path: 'public/resume.pdf',
  format: 'A4',
  printBackground: true,
  preferCSSPageSize: true,   // honour the @page rule in globals.css
});
await browser.close();
server.close();

// Stamp the content hash the freshness check compares against.
const hash = createHash('sha256').update(resumeText(OUT)).digest('hex');
writeFileSync('public/resume.pdf.sha256', `${hash}\n`);

console.log('Wrote public/resume.pdf');
console.log(`Stamped public/resume.pdf.sha256 (${hash.slice(0, 12)}…)`);
// Both files land in public/, and out/ still holds the previous copies until
// the next build — so verify-build.mjs run right now would compare against the
// OLD stamp and report the PDF stale. Say so rather than leaving it to be
// rediscovered.
console.log('\nRun `npm run build` again to copy both into out/ before verifying.');
